/**
 * lib/dataset.ts
 *
 * Loads the bundled tweet pool (`data/tweets.json`, generated by
 * `scripts/build-dataset.mjs`) and sanity-checks it. Used by the seed script
 * and by the local SQLite auto-seed. It is not needed at request time in
 * production, where the pool lives in the database.
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { EMOTION_KEYS } from "./emotions";
import type { TweetSeed } from "./types";

/**
 * Reads and validates `data/tweets.json`.
 *
 * @param file Path to the JSON file (defaults to `<cwd>/data/tweets.json`).
 * @returns The validated tweet pool.
 * @throws Error when the file is malformed or some emotion has no tweets.
 */
export function loadTweetSeeds(file = path.join(process.cwd(), "data", "tweets.json")): TweetSeed[] {
  const tweets = JSON.parse(readFileSync(file, "utf8")) as TweetSeed[];
  const ids = new Set<string>();
  for (const t of tweets) {
    if (!t.id || !t.text || !EMOTION_KEYS.includes(t.groundTruth)) {
      throw new Error(`Malformed tweet in ${file}: ${JSON.stringify(t)}`);
    }
    if (ids.has(t.id)) throw new Error(`Duplicate tweet id ${t.id}`);
    ids.add(t.id);
  }
  for (const emotion of EMOTION_KEYS) {
    if (!tweets.some((t) => t.groundTruth === emotion)) {
      throw new Error(`Tweet pool has no "${emotion}" tweets`);
    }
  }
  return tweets;
}
